@pragma('vm:entry-point')
List<int> hashBucketFillCounts(List<int> keys) {
  int n = keys.length;
  if (n == 0) return [];
  List<int> counts = List.filled(n, 0);
  for (int key in keys) {
    int idx = key % n;
    if (idx < 0) idx += n;
    counts[idx]++;
  }
  return counts;
}

@pragma('vm:entry-point')
void main() {
  assert(hashBucketFillCounts([]).toString() == '[]');
  assert(hashBucketFillCounts([5]).toString() == '[1]');
  assert(hashBucketFillCounts([1, 2, 3]).toString() == '[1, 1, 1]');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = hashBucketFillCounts;

  expect(candidate([]), []);
  expect(candidate([42]), [1]);
  expect(candidate([1, 2]), [1, 1]);
  expect(candidate([-1, -2, -3]), [1, 1, 1]);
  expect(candidate([5, 5, 5]), [0, 0, 3]);
  expect(candidate([1000000, 2000000, 3000000]), [1, 1, 1]);
  expect(candidate([0, 1, 2, 3, 4]), [1, 1, 1, 1, 1]);
  expect(candidate([0, 0, 0]), [3, 0, 0]);
  expect(candidate([5, 10, 15]), [1, 1, 1]);
  expect(candidate([-4, -3, -2, -1, 0, 1, 2, 3]), [1, 1, 1, 1, 1, 1, 1, 1]);
}

