List<int> asciiRowLog(List<int> changeDays, int totalDays) {
  List<int> rows = List.filled(totalDays, 0);
  int c = 0, p = 0;
  for (int d = 0; d < totalDays; d++) {
    if (p < changeDays.length && changeDays[p] == d) c = ++p;
    rows[d] = c;
  }
  return rows;
}

