String filterDNAByDayInterval(String dna, int startDay, int interval) {
  if (interval <= 0) return '';
  StringBuffer sb = StringBuffer();
  for (int i = 0; i < dna.length; i++) {
    if ((i + startDay) % interval == 0) sb.write(dna[i]);
  }
  return sb.toString();
}

