@pragma('vm:entry-point')
bool hasDuplicateShelfInAnyAisle(List<String> codes) {
  var aisleShelves = <String, Set<String>>{};
  for (var code in codes) {
    String aisle = code[0];
    String shelf = code.substring(1);
    if (!aisleShelves.containsKey(aisle)) aisleShelves[aisle] = <String>{};
    if (aisleShelves[aisle]!.contains(shelf)) return true;
    aisleShelves[aisle]!.add(shelf);
  }
  return false;
}

