@pragma('vm:entry-point')
String rowsWithAtLeastFiveSeats(List<String> reservedSeats) {
  var rowCounts = <String, int>{};
  for (var id in reservedSeats) rowCounts.update(id[0], (v) => v + 1, ifAbsent: () => 1);
  var busy = rowCounts.entries.where((e) => e.value >= 5).map((e) => '${e.key}(${e.value})').toList()..sort();
  return busy.isEmpty ? 'none' : busy.join(', ');
}

@pragma('vm:entry-point')
void main() {
  assert(rowsWithAtLeastFiveSeats(["A1","A2","A3","A4","A5"]) == "A(5)");
  assert(rowsWithAtLeastFiveSeats([]) == "none");
  assert(rowsWithAtLeastFiveSeats(["B1","B2","B3","B4"]) == "none");
  print('All tests passed!');
}

