String formatRowsWithReservations(List<String> rows) {
  List<String> result = [];
  for (var i = 0; i < rows.length; i++) {
    if (rows[i].contains('R')) {
      result.add('Row ${i+1}: ${rows[i].split('').join(' ')}');
    }
  }
  if (result.isEmpty) return "No rows with reserved seats";
  return result.join('\n');
