import 'dart:math';

String maxNonAdjacentHashSum(List<String> rows) {
  int prev2 = 0, prev1 = 0;
  for (int i = 0; i < rows.length; i++) {
    int curr = max(prev1, prev2 + '#'.allMatches(rows[i]).length);
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1.toString();
}

