@pragma('vm:entry-point')
List<num> weightedCentroidOfMazeCells(List<List<int>> cells, List<num> weights) {
  double sumX = 0, sumY = 0, totalWeight = 0;
  for (int i = 0; i < cells.length; i++) {
    sumX += cells[i][0] * weights[i];
    sumY += cells[i][1] * weights[i];
    totalWeight += weights[i];
  }
  if (totalWeight == 0) return [0, 0];
  return [sumX / totalWeight, sumY / totalWeight];
}

@pragma('vm:entry-point')
void main() {
  assert(weightedCentroidOfMazeCells([[2,3]], [5]).join(',') == '2.0,3.0');
  assert(weightedCentroidOfMazeCells([[1,1]], [0]).join(',') == '0.0,0.0');
  assert(weightedCentroidOfMazeCells([[0,0],[4,6]], [1,1]).join(',') == '2.0,3.0');
  print('All tests passed!');
}

tests:
