  expect(candidate([[4, 0], [0, 2]], [1, 3]), [1, 1.5]);
  expect(candidate([[1, 2], [3, 4]], [0, 1]), [3, 4]);
  expect(candidate([[-1, -2], [1, 2]], [1, 1]), [0, 0]);
  expect(candidate([[5, 5]], [0]), [0, 0]);
