@pragma('vm:entry-point')
List<String> reconstructBarcodeBitPatterns(List<int> rawDigits, int validBitsMask, int rotateBy) {
  int r = ((rotateBy % 8) + 8) % 8;
  return [for (var d in rawDigits)
    ((d & validBitsMask) >> r | (d & validBitsMask) << (8 - r) & 0xFF)
      .toRadixString(2).padLeft(8, '0')
  ];
}

@pragma('vm:entry-point')
void main() {
  assert(reconstructBarcodeBitPatterns([0x55], 0xFF, 0).toString() == '[01010101]');
  assert(reconstructBarcodeBitPatterns([], 0xFF, 0).toString() == '[]');
  assert(reconstructBarcodeBitPatterns([0xFF, 0x00], 0xFF, 0).toString() == '[11111111, 00000000]');
  print('All tests passed!');
}

tests:
