  final candidate = reconstructBarcodeBitPatterns;

  expect(candidate([0x55], 0xFF, 0), ['01010101']);
  expect(candidate([], 0xFF, 0), []);
  expect(candidate([0xAA], 0x0F, 0), ['00001010']);
  expect(candidate([0x01], 0xFF, 1), ['10000000']);
  expect(candidate([0x80], 0xFF, 7), ['00000001']);
  expect(candidate([0x12], 0xFF, 8), ['00010010']);
  expect(candidate([0x12], 0xFF, -1), ['00100100']);
  expect(candidate([0xAB], 0x55, 2), ['01000000']);
  expect(candidate([0xFF, 0x00, 0x0F], 0xFF, 4), ['11111111', '00000000', '11110000']);
  expect(candidate([0x12, 0x34], 0, 3), ['00000000', '00000000']);
  expect(candidate([0x55], 0xFF, 12345), ['10101010']);
