@pragma('vm:entry-point')
int dnaBitRotation(String dna) {
  const map = {'A':0,'C':1,'G':2,'T':3};
  int v = 0, g = 0;
  for (int i = 0; i < dna.length; i++) {
    int b = map[dna[i]]!;
    v = (v << 2) | b;
    if (b == 2) g++;
  }
  int r = g % 32;
  return ((v >> r) | (v << (32 - r))) & 0xFFFFFFFF;
}

@pragma('vm:entry-point')
