List<String> getDuplicateItemsSortedByFrequency(List<String> items) {
  var counts = <String, int>{};
  for (var item in items) counts[item] = (counts[item] ?? 0) + 1;
  var dupEntries = counts.entries.where((e) => e.value > 1).toList();
  dupEntries.sort((a, b) => b.value.compareTo(a.value) == 0 ? a.key.compareTo(b.key) : b.value.compareTo(a.value));
