import 'dart:math';

List<String> barcodeDigitOverlaps(List<List<int>> bars) {
  List<String> overlaps = [];
  for (int i = 0; i < bars.length - 1; i++) {
    int x = max(0, min(bars[i][2], bars[i+1][2]) - max(bars[i][0], bars[i+1][0]));
    int y = max(0, min(bars[i][3], bars[i+1][3]) - max(bars[i][1], bars[i+1][1]));
