List<int> corridorIndices(List<int> cellMasks) {
  var result = <int>[];
  for (var i = 0; i < cellMasks.length; i++) {
    int mask = cellMasks[i] & 0xF;
    int bits = (mask & 1) + ((mask >> 1) & 1) + ((mask >> 2) & 1) + ((mask >> 3) & 1);
    if (bits == 2) result.add(i);
  }
  return result;
}

