@pragma('vm:entry-point')
String applyPacketSizeAdjustments(int initialSize, List<String> ops) {
  int size = initialSize;
  List<int> stack = [];
  for (var op in ops) {
    if (op.startsWith('add ')) { stack.add(size); size += int.parse(op.substring(4)); }
    else if (op.startsWith('mul ')) { stack.add(size); size *= int.parse(op.substring(4)); }
    else if (op == 'undo') { size = stack.removeLast(); }
  }
  return size.toString();
}

@pragma('vm:entry-point')
