List<String> frequencyOfThermostatSetpoints(List<String> schedule) {
  var freq = <int, int>{};
  for (var s in schedule) {
    freq.update(int.parse(s.split('-').last), (v) => v + 1, ifAbsent: () => 1);
  }
  var entries = freq.entries.toList()..sort((a, b) => a.key.compareTo(b.key));
