@pragma('vm:entry-point')
import 'dart:math';

int playlistMoodRectangleArea(List<int> coords) {
  if (coords.length < 2) return 0;
  int minX = coords[0], maxX = coords[0], minY = coords[1], maxY = coords[1];
  for (int i = 2; i < coords.length; i += 2) {
    int x = coords[i], y = coords[i+1];
    minX = min(minX, x); maxX = max(maxX, x); minY = min(minY, y); maxY = max(maxY, y);
  }
  return (maxX - minX) * (maxY - minY);
}

@pragma('vm:entry-point')
void main() {
  assert(playlistMoodRectangleArea([]) == 0);
  assert(playlistMoodRectangleArea([5,5]) == 0);
  assert(playlistMoodRectangleArea([1,2,3,4]) == 4);
  print('All tests passed!');
}

