String hashBucketRunLength(String input) {
  if (input.isEmpty) return "";
  var result = StringBuffer(), codes = input.codeUnits;
  int prevBucket = codes[0] % 10, run = 1;
  for (int i = 1; i < codes.length; i++) {
    int bucket = codes[i] % 10;
    if (bucket == prevBucket) run++; else { result.write("$prevBucket:$run "); prevBucket = bucket; run = 1; }
  }
  result.write("$prevBucket:$run");
  return result.toString();
}

