String minimalTrainFrequency(List<int> departureMinutes) {
  if (departureMinutes.length < 2) return "0";
  int gcd(int a, int b) => b == 0 ? a : gcd(b, a % b);
  int g = 0;
  for (int i = 1; i < departureMinutes.length; i++) {
    g = gcd(g, (departureMinutes[i] - departureMinutes[0]).abs());
  }
  return g.toString();
}

