import 'dart:math';

List<int> qrModuleBoundingDimensions(List<int> modules) {
  if (modules.isEmpty) return [0, 0];
  int minX = modules[0], maxX = modules[0], minY = modules[1], maxY = modules[1];
  for (int i = 2; i < modules.length; i += 2) {
