bool isBatteryDegrading(List<int> charges) {
  if (charges.length < 2) return false;
  int mid = (charges.length + 1) ~/ 2;
  var firstHalf = charges.sublist(0, mid);
  var secondHalf = charges.sublist(mid);
  double avgFirst = firstHalf.reduce((a, b) => a + b) / firstHalf.length;
  double avgSecond = secondHalf.reduce((a, b) => a + b) / secondHalf.length;
