@pragma('vm:entry-point')
int diceUndoScore(List<int> actions, int undoPenalty) {
  var stack = <int>[], penalty = 0;
  for (var a in actions) {
    if (a > 0) { stack.add(a); }
    else if (a == -1 && stack.isNotEmpty) { stack.removeLast(); penalty += undoPenalty; }
  }
  return stack.fold(0, (a,b) => a + b) - penalty;
}

