String countPrimeBarcodeSegmentations(List<int> digits) {
  if (digits.isEmpty) return "1";
  const primes = {2,3,5,7,11,13,17};
  int dp0 = 1, dp1 = 1;
  for (int i = 2; i <= digits.length; i++) {
    int dp = dp1 + (primes.contains(digits[i-2]+digits[i-1]) ? dp0 : 0);
    dp0 = dp1;
    dp1 = dp;
  }
  return dp1.toString();
}

