List<int> consolidateAndDoubleIngredients(List<String> ingredients) {
  var totals = <String, int>{};
  for (var ing in ingredients) {
    var parts = ing.split(':');
    var name = parts[0];
    var amount = int.parse(parts[1]);
    totals[name] = (totals[name] ?? 0) + amount;
