int medianCardInCutDeck(List<int> deck) {
  int low = 0, high = deck.length - 1;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (deck[mid] > deck[high]) low = mid + 1;
    else high = mid;
  }
  return deck[(low + (deck.length - 1) ~/ 2) % deck.length];
}

