String elevatorWaitTimes(List<List<int>> requests) {
  if (requests.isEmpty) return "";
  const int F = 10;
  var waits = <int>[];
  for (var req in requests) {
    int f = req[0], d = req[1];
    int w = (f - (d % F) + F) % F;
    waits.add(w);
  }
  return waits.join(",");
}

