int nearestMeterCostCents(List<List<int>> meters, List<int> target) {
  if (meters.isEmpty) return 0;
  int minDist = 1 << 62;
  int tx = target[0], ty = target[1];
  for (var m in meters) {
    int dist = (m[0] - tx).abs() + (m[1] - ty).abs();
    if (dist < minDist) minDist = dist;
  }
  return (minDist * 25 + 1) ~/ 2;
}

