bool isValidUpwardLiftSchedule(List<List<int>> grid) {
  int n = grid.length;
  int total = n * n;
  for (int idx = 0; idx < total; idx++) {
    int i = idx ~/ n;
    int j = idx % n;
    if (j <= i && grid[i][j] != 0) return false;
  }
  return true;
}

