List<String> decodeSeatLabels(List<String> obscured, int shift) {
  List<String> result = <String>[];
  for (var s in obscured) {
    int c = s.codeUnitAt(0) - 65;
    int d = (c - shift) % 26;
    if (d < 0) d += 26;
    result.add(String.fromCharCode(d + 65) + s.substring(1));
  }
  return result;
}

