String shiftSpellCheckVowels(String s) {
  const vowels = 'aeiou';
  var result = StringBuffer();
  for (var c in s.split('')) {
    if (vowels.contains(c.toLowerCase())) {
      int idx = vowels.indexOf(c.toLowerCase());
      String next = vowels[(idx + 1) % 5];
      result.write(c == c.toUpperCase() ? next.toUpperCase() : next);
    } else result.write(c);
  } return result.toString(); }

