int asciiRunChecksum(String row) {
  int sum = 0, runLen = 1;
  for (int i = 1; i <= row.length; i++) {
    if (i == row.length || row[i] != row[i-1]) {
      sum += (row[i-1].codeUnitAt(0) % 10) * runLen;
      runLen = 1;
    } else runLen++;
  }
  return sum;
}

