@pragma('vm:entry-point')
double repeatedColorFraction(List<int> pixelColors) {
  var freq = <int, int>{};
  for (var c in pixelColors) {
    freq[c] = (freq[c] ?? 0) + 1;
  }
  int repeatCount = freq.values.where((count) => count > 1).length;
  return freq.isEmpty ? 0.0 : repeatCount / freq.length;
}

