int countBalancedDeckSplits(List<int> deck) {
  if (deck.length < 2) return 0;
  int total = 0, leftSum = 0, rightSum = deck.fold(0, (a, b) => a + b);
  for (int i = 0; i < deck.length - 1; i++) {
    leftSum += deck[i]; rightSum -= deck[i];
    if (leftSum == rightSum)
      total += 1 + countBalancedDeckSplits(deck.sublist(0, i + 1)) + countBalancedDeckSplits(deck.sublist(i + 1));
  }
  return total;
}

