@pragma('vm:entry-point')
String generateLowStockReport(List<String> inventory, int minStock) {
  var totals = <String, int>{};
  for (var entry in inventory) {
    var parts = entry.split('-');
    totals.update(parts[0], (v) => v + int.parse(parts[1]), ifAbsent: () => int.parse(parts[1]));
  }
  var result = totals.entries.where((e) => e.value >= minStock)
      .map((e) => '${e.key}:${e.value}').toList()..sort();
  return result.isEmpty ? 'none' : result.join(', ');
}

