String weightedBucketSpreadDistance(List<List<int>> buckets) {
  if (buckets.isEmpty) return "0";
  buckets.sort((a, b) => a[0] != b[0] ? a[0].compareTo(b[0]) : a[1].compareTo(b[1]));
  int total = 0;
  for (int i = 0; i < buckets.length - 1; i++) {
    total += ((buckets[i][0] - buckets[i + 1][0]).abs() + (buckets[i][1] - buckets[i + 1][1]).abs()) * buckets[i][2] * buckets[i + 1][2];
  }
  return total.toString();
}

