List<String> breakChargePattern(String s, int minSegment) {
  int sum = 0;
  for (int i = 0; i < s.length; i++) sum += int.parse(s[i]);
  String label = sum % 2 == 0 ? "even-cycle" : "odd-dip";
  if (s.length <= minSegment) return [label];
  int mid = s.length ~/ 2;
  return breakChargePattern(s.substring(0, mid), minSegment) + breakChargePattern(s.substring(mid), minSegment);
}

