bool isSortedByMorseWeight(List<String> symbols) {
  for (int i = 0; i < symbols.length - 1; i++) {
    final a = symbols[i];
    final b = symbols[i+1];
    int wa = a.length * 1000 + a.replaceAll('.', '').length;
    int wb = b.length * 1000 + b.replaceAll('.', '').length;
