bool isPacketSizesBalanced(List<int> sizes, int threshold, int maxDiff) {
  int smallCount = sizes.where((s) => s <= threshold).length;
  int largeCount = sizes.length - smallCount;
  return (smallCount - largeCount).abs() <= maxDiff;
}

