bool hasSatellitePassWindow(List<List<int>> snrGrid) {
  const threshold = 10, minWindow = 3;
  int consecutive = 0;
  for (final row in snrGrid) {
    if (row.any((v) => v >= threshold)) {
      consecutive++;
      if (consecutive >= minWindow) return true;
    } else consecutive = 0;
  }
  return false;
}

