@pragma('vm:entry-point')
List<String> simplifyIngredientQuantities(List<String> ingredients) {
  int g(int a, int b) => b == 0 ? a : g(b, a % b);
  if (ingredients.isEmpty) return [];
  int d = int.parse(ingredients[0].split(' ')[0]);
  for (var s in ingredients.skip(1)) d = g(d, int.parse(s.split(' ')[0]));
  return ingredients.map((s) => '${int.parse(s.split(' ')[0]) ~/ d} ${s.split(' ').skip(1).join(' ')}').toList();
}

