import 'dart:math';
int countOverlappingQrModules(List<int> a, List<int> b) {
  int x1 = max(a[0], b[0]);
  int y1 = max(a[1], b[1]);
  int x2 = min(a[2], b[2]);
  int y2 = min(a[3], b[3]);
