@pragma('vm:entry-point')
int maxItemsPerModBucket(List<int> items, int bucketCount) {
  int max = 0;
  Map<int, int> counts = {};
  for (int item in items) {
    int bucket = (item % bucketCount + bucketCount) % bucketCount;
    int newCount = (counts[bucket] ?? 0) + 1;
    counts[bucket] = newCount;
    if (newCount > max) max = newCount;
  }
  return max;
}

@pragma('vm:entry-point')
void main() {
  assert(maxItemsPerModBucket([0, 1, 2], 1) == 3);
  assert(maxItemsPerModBucket([], 5) == 0);
  assert(maxItemsPerModBucket([5], 10) == 1);
  print('All tests passed!');
}

