bool areChargeCyclesSafe(String cycles) {
  bool safe = true;
  List<String> pairs = cycles.split(',').where((p) => p.isNotEmpty).toList();
  for (String pair in pairs) {
    List<String> parts = pair.split('-');
    int start = int.parse(parts[0]);
