String qrVersionModulesToBase(int version, int base) {
  int modules = 21 + 4 * (version - 1);
  if (modules == 0) return "0";
  const String digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  String result = "";
  while (modules > 0) {
    result = digits[modules % base] + result;
    modules ~/= base;
  }
  return result;
}

