String barcodePairwiseSum(String barcode) {
  if (barcode.isEmpty) return "";
  if (barcode.length == 1) return barcode;
  int first = barcode.codeUnitAt(0) - 48;
  int last = barcode.codeUnitAt(barcode.length - 1) - 48;
