List<int> decodeCaesarWifiSignalBins(String encoded) {
  const binMap = {'N': 1, 'O': 2, 'J': 3};
  var result = <int>[];
  for (int i = 0; i < encoded.length; i += 2) {
    int count = int.parse(encoded[i + 1]);
    var binValue = binMap[encoded[i]]!;
    result.addAll(List.filled(count, binValue));
  }
  return result;
}

