int countWeakerPotions(List<int> potions) {
  if (potions.isEmpty) return 0;
  int requirement = potions.last;
  int lo = 0, hi = potions.length - 1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (potions[mid] < requirement) lo = mid + 1; else hi = mid - 1;
  }
  return lo;
}

