String gcdOfMazeSteps(List<int> steps) {
  int dx = (steps[1] - steps[3]).abs(), dy = (steps[0] - steps[2]).abs();
  int a = dx, b = dy;
  while (b != 0) {
    int t = b;
    b = a % b;
    a = t;
  }
  return "gcd($dx,$dy)=$a";
}

