String findDrySpots(List<List<int>> grid) {
  var sb = StringBuffer();
  int cols = grid.isNotEmpty ? grid[0].length : 0;
  for (int i = 0; i < grid.length * cols; i++) {
    int r = i ~/ cols, c = i % cols;
    if (grid[r][c] < 30) {
