List<int> sortTrainTimesByProximity(List<int> times, int target) {
  return List<int>.from(times)..sort((a, b) {
    int da = (a - target).abs();
    int db = (b - target).abs();
    if (da != db) return da.compareTo(db);
    return a.compareTo(b);
