String longestTelemetryUptick(List<int> readings) {
  int maxLen = 0, start = 0;
  for (int end = 1; end <= readings.length; end++) {
    if (end == readings.length || readings[end] <= readings[end - 1]) {
      int len = end - start;
      if (len > maxLen) maxLen = len;
      start = end;
    }
  }
  return maxLen.toString();
}

