String sortInventoryByPriority(List<String> items, List<int> stock) {
  var indices = List.generate(items.length, (i) => i);
  indices.sort((a, b) {
    if (stock[b] != stock[a]) {
      return stock[b].compareTo(stock[a]);
    }
    return items[a].compareTo(items[b]);
  });
  return indices.map((i) => items[i]).join(',');
}

