double scanSquaresAndSumHalfRankFile(String s) {
  double sum = 0.0;
  RegExp pattern = RegExp(r'[a-h][1-8]');
  for (var match in pattern.allMatches(s)) {
    String sq = match.group(0)!;
    int file = sq.codeUnitAt(0) - 96;
    int rank = int.parse(sq[1]);
    sum += (file + rank) / 2.0;
  }
  return sum;
}

