String bracketFormatString(int n) {
  int next = 1;
  while (next < n) {
    next <<= 1;
  }
  int byes = next - n;
  int rounds = next.bitLength - 1;
  int matches = n - 1;
  return 'R$rounds-B$byes-M$matches';
}

