int maxMoistureGapAfterSensorSort(List<int> moistureReadings) {
  List<int> sorted = List.from(moistureReadings);
  sorted.sort((a, b) => (a % 10).compareTo(b % 10) == 0 ? a.compareTo(b) : (a % 10).compareTo(b % 10));
