int maxDiceRoundScore(List<int> diceValues) {
  int bestWithout = 0;
  int bestEnding = -1000000000;
  for (int v in diceValues) {
    int newEnding = (bestEnding + v) > (bestWithout + v - 1) ? (bestEnding + v) : (bestWithout + v - 1);
    bestWithout = bestWithout > newEnding ? bestWithout : newEnding;
    bestEnding = newEnding;
  }
  return bestWithout;
}

