@pragma('vm:entry-point')
String longestEvenFloorStreak(List<int> floors) {
  int maxLen = 0, bestStart = 0, left = 0;
  for (int right = 0; right < floors.length; right++) {
    if (floors[right] % 2 != 0) left = right + 1;
    else if (right - left + 1 > maxLen) { maxLen = right - left + 1; bestStart = left; }
  }
  return maxLen == 0 ? "none" : "$bestStart:$maxLen";
}

