int countShelvesInRadius(Map<String, List<int>> warehouse) {
  var p = warehouse["picker"]!;
  var s = warehouse["shelves"]!;
  int count = 0;
  for (int i = 0; i < s.length; i += 2) {
    int dist = (s[i] - p[0]).abs() + (s[i+1] - p[1]).abs();
    if (dist <= p[2]) count++;
