@pragma('vm:entry-point')
int qrNumericModeBits(int digitCount) {
  final groups = digitCount ~/ 3;
  final remainder = digitCount % 3;
  var bits = groups * 10;
  if (remainder == 1) {
    bits += 4;
  } else if (remainder == 2) {
    bits += 7;
  }
  return bits;
}

@pragma('vm:entry-point')
