List<int> asciiRowSegmentSums(String row, int segments) {
  if (segments == 1) {
    int sum = 0;
    for (int i = 0; i < row.length; i++) sum += row.codeUnitAt(i);
    return [sum];
  }
  int halfSegs = segments ~/ 2;
  return [...asciiRowSegmentSums(row.substring(0, row.length ~/ 2), halfSegs), ...asciiRowSegmentSums(row.substring(row.length ~/ 2), halfSegs)];
}

