@pragma('vm:entry-point')
List<String> classifyBarcodeBarProximities(List<List<int>> barPositions) {
  if (barPositions.isEmpty) return [];
  var labels = <String>['START'];
  for (int i = 1; i < barPositions.length; i++) {
    var a = barPositions[i - 1];
    var b = barPositions[i];
    int d = (b[0] - a[0]).abs() + (b[1] - a[1]).abs();
    labels.add(d <= 5 ? 'NEAR' : 'FAR');
  }
  return labels;
}

