List<int> sortShelfNumbers(List<String> shelfCodes, bool alphabeticalFirst) {
  var indices = List.generate(shelfCodes.length, (i) => i);
  indices.sort((i, j) {
    if (alphabeticalFirst) {
      int cmp = shelfCodes[i][0].compareTo(shelfCodes[j][0]);
      if (cmp != 0) return cmp;
    }
    return int.parse(shelfCodes[i].substring(1)).compareTo(int.parse(shelfCodes[j].substring(1)));
  });
  return indices.map((i) => int.parse(shelfCodes[i].substring(1))).toList();
}

