@pragma('vm:entry-point')
String compressDiceRounds(String rounds) {
  var sb = StringBuffer();
  for (int i = 0; i < rounds.length; ) {
    int j = i;
    while (j < rounds.length && rounds[j] == rounds[i]) j++;
    sb.write('${rounds[i]}:${j - i},');
    i = j;
  }
  var res = sb.toString();
  return res.isEmpty ? "" : res.substring(0, res.length - 1);
}

@pragma('vm:entry-point')
void main() {
  assert(compressDiceRounds('') == '');
  assert(compressDiceRounds('112233') == '1:2,2:2,3:2');
  assert(compressDiceRounds('4444') == '4:4');
  print('All tests passed!');
}

