@pragma('vm:entry-point')
String nibbleSwapFilterIndices(List<int> sizes, int minPriority) {
  List<String> matches = [];
  for (int i = 0; i < sizes.length; i++) {
    int s = sizes[i];
    int swapped = ((s & 0x0F) << 4) | ((s >> 4) & 0x0F);
    if ((swapped >> 4) >= minPriority) matches.add(i.toString());
  }
  return matches.isEmpty ? "none" : matches.join(",");
}

