int maxBucketWeightImbalance(List<int> keys, List<int> weights, int numBuckets) {
  List<int> bucketWeights = List.filled(numBuckets, 0);
  for (int i = 0; i < keys.length; i++) {
    bucketWeights[keys[i] % numBuckets] += weights[i];
