import 'dart:math';

double maxAlternatingChessBonus(List<double> squares) {
  var dp = [0.0, 0.0];
  for (int i = 0; i < squares.length; i++) {
    int p = i % 2;
    dp[p] = max(dp[p], max(dp[1 - p] + squares[i], squares[i]));
