int tallyDecisivePrecincts(List<List<int>> precinctVotes, int candidateIndex, int minVoters) {
  int count = 0;
  for (var row in precinctVotes) {
    int total = row.reduce((a, b) => a + b);
    if (row[candidateIndex] * 2 > total && total >= minVoters) {
