import 'dart:math';

int longestBarcodeSegmentInRange(List<int> barcodeDigits, int low, int high) {
  int maxLen = 0, left = 0, sum = 0;
  for (int right = 0; right < barcodeDigits.length; right++) {
    sum += barcodeDigits[right];
    while (sum > high && left <= right) sum -= barcodeDigits[left++];
    if (sum >= low) maxLen = max(maxLen, right - left + 1);
  }
  return maxLen;
}

