num severityWeightedLogDistanceSum(List<List<int>> logs, List<int> target) {
  int tx = target[0], ty = target[1];
  int sum = 0;
  for (final log in logs) {
    int dx = (log[0] - tx).abs();
    int dy = (log[1] - ty).abs();
    sum += (dx + dy) * log[2];
  }
  return sum;
}

