@pragma('vm:entry-point')
String checkShapePasswordStrength(List<List<int>> points, int minArea) {
  int n = points.length;
  if (n < 3) return "weak";
  int twiceArea = 0;
  for (int i = 0; i < n; i++) {
    int j = (i + 1) % n;
    twiceArea += points[i][0] * points[j][1] - points[j][0] * points[i][1];
  }
  twiceArea = twiceArea.abs();
  return (twiceArea >= 2 * minArea) ? "strong" : "weak";
}

