int countEvenSumEntriesAboveThreshold(List<List<int>> ledger, int threshold) {
  int rows = ledger.length, cols = rows == 0 ? 0 : ledger[0].length, count = 0;
  for (int i = 0; i < rows * cols; i++) {
    int row = i ~/ cols;
    int col = i % cols;
    if ((row + col) % 2 == 0 && ledger[row][col] > threshold) {
      count++;
    }
  }
  return count;
}

