List<String> maxAsciiArtRowSegment(List<String> rows, int maxStones) {
  int left=0, sum=0, mx=0, best=0;
  for (int i=0; i<rows.length; ++i) {
    sum += rows[i].split('#').length-1;
    while (sum > maxStones) sum -= rows[left++].split('#').length-1;
    if (i-left+1 > mx) { mx=i-left+1; best=left; }
  }
  return rows.sublist(best,best+mx);
}

