List<int> doubleIngredientAmounts(List<String> recipe) {
  Map<String, int> totals = {};
  for (var item in recipe) {
    var parts = item.split(':');
    String name = parts[0];
    int amount = int.parse(parts[1]);
    totals[name] = (totals[name] ?? 0) + amount;
