List<int> compactColorRuns(List<int> colors) {
  if (colors.isEmpty) return [];
  var res = <int>[];
  int cnt = 1, prv = colors[0];
  for (int i = 1; i < colors.length; i++)
    if (colors[i] == prv) cnt++;
    else { res.add(cnt); res.add(prv); prv = colors[i]; cnt = 1; }
