num rotateShelfCodeByPopcount(int shelfCode) {
  int code = shelfCode & 0xFF;
  int pop = 0;
  for (int t = code; t > 0; t >>= 1) pop += t & 1;
  int rot = pop % 8;
  int rotated = ((code << rot) | (code >> (8 - rot))) & 0xFF;
  return rotated;
}

