int longestRunInShiftedSchedule(String schedule) {
  int maxRun = 0, currentRun = 0, prev = -1;
  for (int i = 0; i < schedule.length; i++) {
    int shifted = ((schedule.codeUnitAt(i) - 65 + 3) % 26) + 65;
    if (shifted == prev) currentRun++; else currentRun = 1;
    if (currentRun > maxRun) maxRun = currentRun;
