List<String> tideReadingFrequenciesAboveOne(List<int> readings) {
  var freq = <int,int>{};
  for (var h in readings) {
    freq.update(h, (v) => v + 1, ifAbsent: () => 1);
  }
  var filtered = freq.entries.where((e) => e.value > 1).toList()..sort((a,b) => b.value != a.value ? b.value.compareTo(a.value) : a.key.compareTo(b.key));
  return filtered.map((e) => '${e.key}:${e.value}').toList();
}

