String topRowByRankSum(List<List<String>> deck) {
  if (deck.isEmpty) return "none";
  int bestIdx = -1, bestSum = -1;
  for (int i = 0; i < deck.length; i++) {
    int sum = deck[i].fold(0, (int acc, String card) => acc + "A23456789TJQK".indexOf(card[0]) + 1);
