@pragma('vm:entry-point')
bool hasServiceUnavailable(List<int> sortedErrorCodes) {
  int low = 0, high = sortedErrorCodes.length - 1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedErrorCodes[mid] == 503) return true;
    else if (sortedErrorCodes[mid] < 503) low = mid + 1;
    else high = mid - 1;
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasServiceUnavailable([503]) == true);
  assert(hasServiceUnavailable([500, 502]) == false);
  assert(hasServiceUnavailable([]) == false);
