bool hasBatteryCompletedCycles(List<int> dailyDeltas, int startCharge, int requiredCycles) {
  int charge = startCharge, cycles = 0;
  bool wasEmpty = charge == 0;
  for (int d in dailyDeltas) {
    charge = (charge + d).clamp(0, 100);
    if (charge == 0) wasEmpty = true; else if (charge == 100 && wasEmpty) { cycles++; wasEmpty = false; }
  }
  return cycles >= requiredCycles;
}

