@pragma('vm:entry-point')
List<int> sortLogIndicesBySeverityAndLength(List<String> logLines) {
  var weights = {'CRITICAL':5, 'ERROR':4, 'WARNING':3, 'INFO':2, 'DEBUG':1};
  var indices = List.generate(logLines.length, (i) => i);
  indices.sort((i,j) {
    var li = logLines[i], lj = logLines[j];
    int cmp = weights[li.substring(0, li.indexOf(':'))]!.compareTo(weights[lj.substring(0, lj.indexOf(':'))]!);
    if (cmp != 0) return -cmp;
    return lj.substring(lj.indexOf(':')+1).length.compareTo(li.substring(li.indexOf(':')+1).length);
  });
  return indices;
}

