@pragma('vm:entry-point')
int roundCentsByPopcount(int amount) {
  int n = amount;
  int pop = 0;
  while (n != 0) {
    pop += n & 1;
    n >>= 1;
  }
  int offset = (pop % 5) - 2;
  return (amount + offset + 2) ~/ 5 * 5;
}

