List<int> sortDnaIndicesByGc(List<String> dnaStrings, bool ascending) {
  var indexed = <List<int>>[];
  for (int i = 0; i < dnaStrings.length; i++) {
    final s = dnaStrings[i];
    indexed.add([i, 'G'.allMatches(s).length + 'C'.allMatches(s).length]);
  }
  indexed.sort((a, b) => a[1] != b[1] ? (ascending ? a[1] - b[1] : b[1] - a[1]) : a[0].compareTo(b[0]));
