@pragma('vm:entry-point')
int decodeParityBarcodeDigit(int encoded) {
  int b = encoded & 0x7F;
  int c = b - ((b >> 1) & 0x55);
  c = (c & 0x33) + ((c >> 2) & 0x33);
  c = (c + (c >> 4)) & 0x0F;
  int digit = b & 0xF;
  return ((c & 1) == 1 && digit <= 9) ? digit : -1;
}

@pragma('vm:entry-point')
