String countPrecinctsWithMinVotes(List<int> sortedVotes, int minVotes) {
  int low = 0, high = sortedVotes.length;
  while (low < high) {
    int mid = (low + high) ~/ 2;
    if (sortedVotes[mid] < minVotes) low = mid + 1;
