int calculateElectionTallyWithUndo(int initialTally, List<int> voteBatches, int threshold) {
  var stack = [initialTally];
  for (var batch in voteBatches) {
    var newTotal = stack.last + batch;
    stack.add(newTotal);
    if (newTotal > threshold) {
      stack.removeLast();
    }
  }
  return stack.last;
}

