String passwordDivisibilityCheck(String password) {
  int product = 1, sum = 0;
  for (int i = 0; i < password.length; i++) {
    int d = int.parse(password[i]); product *= d; sum += d;
  }
  if (sum == 0) return 'invalid';
  return product % sum == 0 ? 'valid' : 'invalid';
}

