int countDarkSquares(String squares) {
  if (squares.isEmpty) return 0;
  int count = 0;
  for (var s in squares.split(',')) {
    int col = s.codeUnitAt(0) - 'a'.codeUnitAt(0);
    int row = int.parse(s.substring(1)) - 1;
