@pragma('vm:entry-point')
String decodeBarcodeZigzag(List<List<int>> grid) {
  int rows = grid.length, cols = rows == 0 ? 0 : grid[0].length;
  StringBuffer sb = StringBuffer();
  for (int i = 0; i < rows * cols; i++) {
    int r = i ~/ cols, c = i % cols;
    if (r % 2 == 1) c = cols - 1 - c;
    sb.write(grid[r][c]);
  }
  return sb.toString();
}

@pragma('vm:entry-point')
