import 'dart:math';

double computeWinnerRating(List<double> ratings) {
  if (ratings.length == 1) return ratings[0];
  int m = ratings.length ~/ 2;
  double left = computeWinnerRating(ratings.sublist(0, m));
  double right = computeWinnerRating(ratings.sublist(m));
