bool isBucketLoadCappedByVariety(List<int> hashValues) {
  Map<int,int> freq = {};
  for (var v in hashValues) {
    freq.update(v, (c) => c+1, ifAbsent: () => 1);
  }
  int maxFreq = 0;
  for (var c in freq.values) {
    if (c > maxFreq) maxFreq = c;
  }
  return maxFreq <= freq.length;
}

