@pragma('vm:entry-point')
import 'dart:math';

List<int> manhattanDistancesToInventoryCenter(List<List<int>> positions) {
  if (positions.isEmpty) return [];
  int minX = positions[0][0], maxX = positions[0][0], minY = positions[0][1], maxY = positions[0][1];
  for (var p in positions.skip(1)) {
    minX = min(minX, p[0]); maxX = max(maxX, p[0]); minY = min(minY, p[1]); maxY = max(maxY, p[1]);
  }
  int cx = (minX + maxX) ~/ 2, cy = (minY + maxY) ~/ 2;
  return List.generate(positions.length, (i) => (positions[i][0] - cx).abs() + (positions[i][1] - cy).abs());
}

