@pragma('vm:entry-point')
int undoChargeLog(List<String> events, int initialCharge) {
  int charge = initialCharge;
  List<int> stack = [];
  for (final event in events) {
    if (event == 'undo') charge -= stack.removeLast();
    else charge += (stack..add(int.parse(event))).last;
  }
