@pragma('vm:entry-point')
List<int> longestUniqueSongSegment(List<int> songIDs) {
  int left = 0, start = 0, maxLen = 0;
  Set<int> seen = {};
  for (int right = 0; right < songIDs.length; right++) {
    while (seen.contains(songIDs[right])) seen.remove(songIDs[left++]);
    seen.add(songIDs[right]);
    if (right - left + 1 > maxLen) { maxLen = right - left + 1; start = left; }
  }
  return maxLen == 0 ? <int>[] : songIDs.sublist(start, start + maxLen);
}

