  var res = <List<int>>[];
  for (var b in boxes) if ((pt[0]-b[0]).abs()+(b[2]-pt[0]).abs()+(pt[1]-b[1]).abs()+(b[3]-pt[1]).abs()==(b[2]-b[0])+(b[3]-b[1])) res.add(b);
