bool isSortedByRedBlueDiffThenGreen(List<int> pixels) {
  for (int i = 0; i < pixels.length - 1; i++) {
    int r1 = (pixels[i] >> 16) & 0xFF, g1 = (pixels[i] >> 8) & 0xFF, b1 = pixels[i] & 0xFF;
    int r2 = (pixels[i+1] >> 16) & 0xFF, g2 = (pixels[i+1] >> 8) & 0xFF, b2 = pixels[i+1] & 0xFF;
    int diff1 = r1 - b1, diff2 = r2 - b2;
    int order = (diff1 != diff2) ? (diff1 - diff2) : (g2 - g1);
    if (order > 0) return false;
  }
  return true;
}

