import 'dart:math';
int countRowsWithEmptyPair(List<int> seats, int rowWidth) {
  int count = 0, consecutiveEmpty = 0, maxStreak = 0;
  for (int i = 0; i < seats.length; i++) {
    if (seats[i] == 0) { consecutiveEmpty++; maxStreak = max(maxStreak, consecutiveEmpty); }
