@pragma('vm:entry-point')
List<String> findNearestQrModulesToOrigin(List<List<int>> modulePositions) {
  var minDist = 1<<30;
  var closest = <List<int>>[];
  for (var p in modulePositions) {
    int dist = p[0].abs() + p[1].abs();
    if (dist < minDist) { minDist = dist; closest = [p]; }
    else if (dist == minDist) { closest.add(p); }
  }
  return closest.map((p) => '(${p[0]},${p[1]}):$minDist').toList();
}

@pragma('vm:entry-point')
