@pragma('vm:entry-point')
int countEvenTotalPorts(List<String> manifestEntries) {
  var portCounts = <String, int>{};
  for (var entry in manifestEntries) {
    var parts = entry.split(':');
    var port = parts[0];
    int count = int.parse(parts[1]);
    portCounts.update(port, (int current) => current + count, ifAbsent: () => count);
  }
  return portCounts.values.where((int v) => v % 2 == 0).length;
}

@pragma('vm:entry-point')
void main() {
  assert(countEvenTotalPorts([]) == 0);
  assert(countEvenTotalPorts(["A:2"]) == 1);
