List<int> arrangeCardsByParity(List<int> deck) {
  if (deck.length <= 1) return deck;
  int first = deck[0];
  List<int> rest = deck.sublist(1);
  List<int> arrangedRest = arrangeCardsByParity(rest);
  if (first % 2 == 0) {
    return [first] + arrangedRest;
  } else {
    return arrangedRest + [first];
  }
}

