List<int> countMorseSegments(List<List<int>> points) {
  int dots = 0, dashes = 0;
  for (int i = 1; i < points.length; i++) {
    int dist = (points[i][0] - points[i-1][0]).abs() + (points[i][1] - points[i-1][1]).abs();
