String compressInventoryLabel(String label) {
  var sb = StringBuffer();
  for (int i = 0; i < label.length; ) {
    int start = i++;
    while (i < label.length && label[i] == label[start]) i++;
    int count = i - start;
    if (count >= 4) sb.write('$count${label[start]}');
    else sb.write(label.substring(start, i));
  }
  return sb.toString();
}

