int toleranceCount(List<int> distances) {
  if (distances.isEmpty) return 0;
  int threshold = distances[0] + 1, left = 0, right = distances.length - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (distances[mid] <= threshold) left = mid + 1;
    else right = mid - 1;
  }
  return right + 1;
}

