import 'dart:math';
String gridCellBoundingArea(List<List<int>> cells) {
  if (cells.isEmpty) return "No cells";
  int minX = cells[0][0], maxX = cells[0][0], minY = cells[0][1], maxY = cells[0][1];
  for (int i = 1; i < cells.length; i++) {
    minX = min(minX, cells[i][0]); maxX = max(maxX, cells[i][0]);
    minY = min(minY, cells[i][1]); maxY = max(maxY, cells[i][1]);
  }
  return "${(maxX - minX + 1) * (maxY - minY + 1)}";
}

@pragma('vm:entry-point')
