@pragma('vm:entry-point')
String scaleRecipeToSmallestRatio(List<int> amounts) {
  if (amounts.isEmpty) return '';
  int g = amounts[0];
  for (int i = 1; i < amounts.length; i++) {
    g = _gcd(g, amounts[i]);
  }
  return amounts.map((a) => (a ~/ g).toString()).join(':');
}

int _gcd(int a, int b) => b == 0 ? a : _gcd(b, a % b);

@pragma('vm:entry-point')
