bool validateLogChecksum(String logLine) {
  if (logLine.length < 2) return false;
  int sum = 0;
  for (int i = 0; i < logLine.length - 2; i++) sum += logLine.codeUnitAt(i);
  String checksumHex = logLine.substring(logLine.length - 2);
  int expected = int.parse(checksumHex, radix: 16);
  return (sum % 256) == expected;
