import 'dart:math';
int qrModuleManhattanDiameter(List<List<int>> modules) {
  if (modules.isEmpty) return 0;
  var first = modules.first;
  int minSum = first[0]+first[1], maxSum = minSum, minDiff = first[0]-first[1], maxDiff = minDiff;
  for (var m in modules) {
    int sum = m[0]+m[1], diff = m[0]-m[1];
    minSum = min(minSum, sum); maxSum = max(maxSum, sum); minDiff = min(minDiff, diff); maxDiff = max(maxDiff, diff);
  }
  return max(maxSum - minSum, maxDiff - minDiff);
}

