@pragma('vm:entry-point')
String thermostatScheduleInterval(List<int> times) {
  if (times.length < 2) return "Insufficient data";
  int result = (times[1] - times[0]).abs();
  int gcd(int a, int b) => b == 0 ? a : gcd(b, a % b);
  for (int i = 2; i < times.length; i++) {
    int diff = (times[i] - times[i-1]).abs();
    result = gcd(result, diff);
  }
  return "Optimal interval: ${result}h";
}

