List<int> sortPassWindowsByStartDuration(List<List<int>> windows) {
  var sorted = List<List<int>>.from(windows);
  sorted.sort((a, b) {
    if (a[0] != b[0]) return a[0].compareTo(b[0]);
    return b[1].compareTo(a[1]);
  });
  return sorted.map((w) => w[0]).toList();
}

