List<int> categorizeVibrationSamples(List<double> readings, List<double> thresholds) {
  double low = thresholds[0], high = thresholds[1];
  int lowCount = 0, normalCount = 0, highCount = 0;
  for (var r in readings) {
    if (r < low) lowCount++; else if (r > high) highCount++; else normalCount++;
