@pragma('vm:entry-point')
String findShelfContainingPoint(List<List<int>> input) {
  int px = input[0][0], py = input[0][1];
  for (int i = 1; i < input.length; i++) {
    int x = input[i][0], y = input[i][1], w = input[i][2], h = input[i][3];
    if ((px - x) * (px - x - w + 1) <= 0 && (py - y) * (py - y - h + 1) <= 0) return (i - 1).toString();
  }
  return "none";
}

