int rlePacketSize(String packet) {
  int total = 0, i = 0;
  while (i < packet.length) {
    int j = i;
    while (j < packet.length && packet[j] == packet[i]) j++;
    int runLen = j - i;
    total += runLen.toString().length + 1;
    i = j;
