int soilMoistureRleSurplus(String compressed, int threshold) {
  int surplus = 0;
  for (int i = 0; i < compressed.length; i += 2) {
    int count = int.parse(compressed[i]);
    int moisture = compressed.codeUnitAt(i + 1) - 65 + 1;
    if (moisture > threshold) {
