List<double> smoothBucketCounts(List<int> counts, double alpha) {
  if (counts.isEmpty) return [];
  var result = <double>[counts[0].toDouble()];
  double prev = result[0];
  for (int i = 1; i < counts.length; i++) {
    prev = alpha * counts[i] + (1 - alpha) * prev;
    result.add(prev);
  }
  return result;
}

