bool isMirrorDiceRound(List<int> rolls) {
  int sum = rolls.fold(0, (a, b) => a + b);
  String base6 = (sum == 0) ? '0' : '';
  int n = sum;
  while (n > 0) {
    base6 = (n % 6).toString() + base6;
