List<int> wifiSlidingWindowBins(List<int> signals) {
  var queue = <int>[], counts = [0,0,0];
  for (var s in signals) {
    int bin = s > -40 ? 0 : s >= -70 ? 1 : 2;
    counts[bin]++;
    queue.add(bin);
    if (queue.length > 3) counts[queue.removeAt(0)]--;
  }
  return counts;
}

