import 'dart:math' show max;

String maxIntervalBetweenABases(String seq) {
  int lastA = -1, maxDist = 0;
  for (int i = 0; i < seq.length; i++) {
    if (seq[i] == 'A') {
      if (lastA != -1) maxDist = max(maxDist, i - lastA);
