bool isQrRowBlackPrime(int row) {
  int count = 0, n = row;
  while (n > 0) { count += n & 1; n >>= 1; }
  bool result = count > 1;
  for (int i = 2; i * i <= count && result; i++) {
    if (count % i == 0) result = false;
  }
  return result;
}

