bool hasRowWithExactHashCount(List<String> rows, int targetCount) {
  int low = 0, high = rows.length - 1;
  while (low <= high) {
    int mid = (low + high) ~/ 2;
    int count = rows[mid].split('#').length - 1;
    if (count == targetCount) return true;
    if (count < targetCount) low = mid + 1;
    else high = mid - 1;
  }
  return false;
}

