bool hasFullErrorColumn(List<String> logLines) {
  if (logLines.isEmpty) return false;
  int rows = logLines.length, cols = logLines[0].length;
  var colFlags = List.filled(cols, true);
  for (int i = 0; i < rows * cols; i++) {
    int r = i ~/ cols, c = i % cols;
    if (logLines[r][c] != 'E') colFlags[c] = false;
  }
  return colFlags.any((f) => f);
}

