List<String> processThermostatUndo(List<String> commands) {
  List<String> stack = [], redo = [];
  for (String cmd in commands) {
    if (cmd == "undo") { redo.add(stack.removeLast()); }
    else if (cmd == "redo") { stack.add(redo.removeLast()); }
