double totalGreenDurationAfterUndo(List<String> actions) {
  List<int> stack = [];
  for (final action in actions) {
    if (action == "UNDO") {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(int.parse(action.substring(1)));
    }
  }
  return stack.fold<int>(0, (sum, d) => sum + d).toDouble();
}

