bool isCoprimeDiceGame(List<int> diceRolls) {
  int gcd(int a, int b) => b == 0 ? a : gcd(b, a % b);
  int sum = 0;
  for (int i = 0; i < diceRolls.length; i++) {
    sum += diceRolls[i];
    if (gcd(sum, i + 1) != 1) return false;
  }
  return true;
}

