List<int> elevatorSegments(List<List<int>> requests) {
  var current = [0, 0];
  var result = <int>[];
  for (var r in requests) {
    int px = r[0], py = r[1], dx = r[2], dy = r[3];
    result.add((px - current[0]).abs() + (py - current[1]).abs());
    result.add((dx - px).abs() + (dy - py).abs());
    current = [dx, dy];
  }
  return result;
}

