List<int> playlistHighRatingSums(List<List<int>> ratings) {
  if (ratings.isEmpty) return [];
  int cols = ratings[0].length;
  List<int> result = List.filled(ratings.length, 0);
  for (int i = 0; i < ratings.length * cols; i++) {
    int val = ratings[i ~/ cols][i % cols];
    if (val >= 4) result[i ~/ cols] += val;
  }
  return result;
