import 'dart:math';

int totalOverlappingTideZoneArea(List<List<int>> tideZones, List<int> queryZone) {
  int total = 0;
  for (var zone in tideZones) {
    int x_overlap = max(0, min(zone[2], queryZone[2]) - max(zone[0], queryZone[0]));
    int y_overlap = max(0, min(zone[3], queryZone[3]) - max(zone[1], queryZone[1]));
    total += x_overlap * y_overlap;
  }
  return total;
}

