@pragma('vm:entry-point')
int countSongsExceedingDuration(String durations, int secondsLimit) {
  if (durations.isEmpty) return 0;
  int count = 0;
  for (String token in durations.split(';')) {
    List<String> parts = token.trim().split(':');
    int minutes = int.parse(parts[0]);
    int secs = int.parse(parts[1]);
    if (minutes * 60 + secs > secondsLimit) count++;
  }
  return count;
}

