List<int> countSpellCheckEdits(List<String> edits) {
  var counts = {'ins': 0, 'del': 0, 'sub': 0, 'trans': 0};
  for (var e in edits) {
    counts.update(e, (v) => v + 1, ifAbsent: () => 1);
