List<String> telemetryCalibrationStatuses(List<int> data) {
  if (data.length <= 1) return [];
  int interval = data[0];
  List<String> result = [];
  for (int i = 1; i < data.length; i++) {
    int day = data[i];
    int daysUntil = (interval - (day % interval)) % interval;
    result.add('$day->${daysUntil}d');
  }
