List<num> prioritizeLedgerEntries(List<num> amounts) {
  final sorted = List<num>.from(amounts);
  sorted.sort((a, b) {
    int absComp = b.abs().compareTo(a.abs());
    if (absComp != 0) return absComp;
    return b.compareTo(a);
