String decodeShiftedTally(String encoded) {
  var result = '';
  for (int i = 0; i < encoded.length; i += 2) {
    var letter = encoded[i];
    int shifted = int.parse(encoded[i+1]);
    int count = (shifted - 1 + 10) % 10;
    result += letter * count;
  }
  return result;
}

