@pragma('vm:entry-point')
int countActiveHashBuckets(String data) {
  var words = data.split(' ').where((w) => w.isNotEmpty);
  var buckets = List.filled(10, 0);
  for (var word in words) {
    buckets[word.codeUnits.fold(0, (a, b) => a + b) % 10]++;
  }
  return buckets.where((v) => v > 0).length;
}

